## 6. 验证纪律（本项目最重要的工程约定）

**执行方（人或 agent）的自述不能作为验收依据。** 每条结论都要用**不同手段**独立复验。已验证有效的手段：

| 手段 | 曾发现的问题 |
|---|---|
| 直接聚合 `target/surefire-reports/*.txt` 算测试数（不读执行方日志） | 多次校正基线 |
| 独立 diff / SHA-256 比对（含 `git diff --no-index`） | 证明行为无字节偏差 |
| 自写探针直连生产路径 | 证明缓存 schema 与命中判定正确 |
| 方法/字段级存量对账（元数据修改前后） | 证明去重没丢条目 |
| 字节码常量池扫描（而非 grep import） | 发现全限定名引用可绕过 import 扫描 |
| 跑 GUI 前先删结果文件、跑完核对 **mtime** | 被"上一次的 34/0"骗过一次 |
package com.mhtextractor.backend;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mhtextractor.app.*;
import com.mhtextractor.core.SourceParsers;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.ParamScope;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.model.ThumbnailData;
import com.mhtextractor.uiport.*;

import java.io.IOException;
import java.lang.management.ManagementFactory;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/** Backend host assembly. All model commands and callbacks run on the serial IPC host thread. */
final class IpcSession implements AutoCloseable {
    static final List<String> METHODS = List.of("importPaths", "group", "setParams", "extract",
            "workspacePage", "previewFiles", "fileInfo", "releaseFiles", "metrics", "confirmAnswer");
    static final List<String> STRUCTURE_METHODS = List.of(
            "ungroup", "renameGroup", "toggleGroupExpanded", "clearItems", "applyDrop", "removeItems", "removeGroup", "canUndo");
    static final List<String> ACTIVITY_METHODS = List.of("cancelWorkspaceActivity", "cancelPreviewLoad",
            "startPreparse", "startPreparseFor", "refreshPreparseProgress", "loadPreview",
            "resolvePreviewRegion", "awaitPreviewInFlight", "applyImportPlan",
            "activityGeneration", "previewGeneration", "previewLoadingPath");
    static final List<String> PARAM_METHODS = List.of("setGlobalParams", "setGroupParams", "setItemParams",
            "clearParams", "applyGlobalParams", "undo", "runtimeConfig", "outputUnitPlan", "paramSchema");
    private final ObjectMapper json;
    private final WorkspaceModel model = new WorkspaceModel();
    private final GlobalParameterCache global = new GlobalParameterCache();
    private final ArrayBlockingQueue<Runnable> callbacks = new ArrayBlockingQueue<>(256);
    private final Thread host = Thread.currentThread();
    private final IpcFiles files;
    private final PreviewSession previews;
    private final PreviewService previewService;
    private final WorkspaceExtractionCoordinator extractions;
    private final IpcConfirmations confirmations;
    final Uiport port;
    private Consumer<ObjectNode> events;
    private boolean importDone;
    private boolean importFailed;
    private PortEvent.ExtractionTerminal terminal;
    private boolean imageMode;
    private String outputFolder;
    private int progressBucket = -1;
    private long rawProgress;
    private long sentProgress;
    private volatile int queuePeak;
    private volatile boolean closing;
    private volatile boolean disconnecting;
    private boolean importing;
    private boolean applyingPlan;
    private boolean activityImageMode;
    private final java.util.Set<Thread> workers = java.util.concurrent.ConcurrentHashMap.newKeySet();
    private final java.util.List<String> importChanges = new java.util.ArrayList<>();
    private final java.util.Map<Long, PreviewService.Prepared> previewInputs = new java.util.HashMap<>();
    private final java.util.Map<Long, java.util.List<PortEvent.PreviewNotice>> pendingNotices = new java.util.HashMap<>();
    private final IpcWorkspaceCodec codec;
    private final IpcParamCodec paramCodec;
    private Runnable inputPump = () -> { };
    private Runnable silentChange = () -> { };

    IpcSession(ObjectMapper json) throws IOException {
        this.json = json;
        confirmations = new IpcConfirmations(json, this::dispatch, data -> emit("confirmationRequested", data),
                data -> emit("confirmationExpired", data));
        files = new IpcFiles(json);
        codec = new IpcWorkspaceCodec(json, files);
        paramCodec = new IpcParamCodec(json);
        previews = PreviewSession.create(files.root.resolve("preview-cache"));
        previewService = new PreviewService(previews.lifecycle());
        var plans = new ExtractionPlanService(new ExtractionPlanService.Context() {
            public List<Object> dataOrder() { return model.topLevel(); }
            public boolean imageMode() { return imageMode; }
            public AppConfig textParamsCache() { return global.text(); }
            public AppConfig imageParamsCache() { return global.image(); }
            public String inputFolder() { return null; }
            public String outputFolder() { return outputFolder; }
            public boolean openFolderAfterComplete() { return false; }
        });
        Confirmer confirmer = confirmations;
        var activities = new WorkspaceActivityService(new WorkspaceActivityService.Context() {
            public List<PreviewItem> items() { return model.allItems(); }
            public boolean textMode() { return !activityImageMode; }
            public AppConfig effectiveParams(PreviewItem item) { return params(item, activityImageMode); }
            public AppConfig effectiveImageParams(PreviewItem item) { return params(item, true); }
        }, previewService, IpcImages::thumbnail, this::dispatch);
        var clipboard = new ParamClipboard(model::push, target -> ParamScope.GLOBAL, (target, mode, config) -> { });
        var paramCommands = new WorkspaceParamCommandService(model, new WorkspaceParamService(previews.lifecycle()),
                global, clipboard::pushParamUndo);
        // A server import round is bounded to 20k inputs; continuing requires a client decision.
        var imports = new WorkspaceImportCoordinator(model, confirmer, this::dispatch, 200, 20000);
        extractions = new WorkspaceExtractionCoordinator(new WorkspaceExtractionService(previews.lifecycle()),
                WorkspaceExtractionCoordinator.productionRequests(plans,
                        () -> model.allItems().stream().filter(item -> !item.removed).toList(), confirmer), this::dispatch);
        port = new InProcessUiport(model, confirmer, plans, activities, paramCommands, imports, extractions,
                new WorkspaceParamService(previews.lifecycle()));
        port.events().subscribe(this::onEvent);
    }

    void events(Consumer<ObjectNode> sink) { events = sink; }

    IpcFiles files() { return files; }

    void silentChanges(Runnable changed) { silentChange = changed; }

    void drainCallbacks() {
        for (int i = 0; i < 256; i++) {
            var callback = callbacks.poll();
            if (callback == null) return;
            callback.run();
        }
    }

    void inputPump(Runnable pump) { inputPump = pump; }

    void disconnect() {
        if (disconnecting) return;
        disconnecting = true;
        try {
            // Mark the run cancelled before waking its confirmation waiter; otherwise it may win a natural-completion race.
            port.commands().cancelExtraction();
        } finally {
            confirmations.disconnect(); // Also release import confirmations, even if terminal delivery broke stdout.
            if (port.queries().previewLoadingPath() != null
                    || workers.stream().anyMatch(t -> t.isAlive() && t.getName().equals("preview-preparse")))
                port.commands().cancelWorkspaceActivity();
        }
    }

    private AppConfig params(PreviewItem item, boolean mode) {
        AppConfig config = ParamScope.effectiveParams(item.parentGroup, item.textItemParams,
                item.imageItemParams, mode, global.text(), global.image());
        return config == null ? new AppConfig() : config;
    }

    private void dispatch(Runnable callback) {
        if (closing) return;
        if (Thread.currentThread() == host) { callback.run(); return; }
        String workerName = Thread.currentThread().getName();
        if (workerName.startsWith("preview-") || workerName.startsWith("mht-import-") || workerName.startsWith("extraction-"))
            workers.add(Thread.currentThread());
        boolean interrupted = false;
        try {
            while (!closing) {
                try {
                    if (callbacks.offer(callback, 25, TimeUnit.MILLISECONDS)) break;
                } catch (InterruptedException e) { interrupted = true; }
            }
            queuePeak = Math.max(queuePeak, callbacks.size());
        } finally {
            if (interrupted) Thread.currentThread().interrupt();
        }
    }

    private void start(Runnable command) {
        var before = Thread.getAllStackTraces().keySet();
        command.run();
        // Existing app coordinators create these workers synchronously before returning.
        // Keep their handles so shutdown also joins a parser that has not delivered a callback yet.
        Thread.getAllStackTraces().keySet().stream().filter(t -> !before.contains(t))
                .filter(t -> t.getName().equals("preview-preparse") || t.getName().equals("preview-image-load")
                        || t.getName().equals("mht-import-scan")).forEach(workers::add);
    }

    boolean busy() { return importing || !pendingNotices.isEmpty() || port.queries().previewLoadingPath() != null
            || workers.stream().anyMatch(t -> t.isAlive() && t.getName().equals("preview-preparse")); }

    private void await(java.util.function.BooleanSupplier done) throws InterruptedException {
        // Synchronous methods finish their activity before responding; no worker touches the model afterward.
        while (!done.getAsBoolean()) {
            inputPump.run();
            Runnable callback = callbacks.poll(25, TimeUnit.MILLISECONDS);
            if (callback != null) callback.run();
        }
    }

    private void emit(String name, ObjectNode data) {
        ObjectNode frame = json.createObjectNode().put("v", 1).put("type", "event").put("event", name);
        frame.set("data", data);
        events.accept(frame);
    }

    private void onEvent(PortEvent event) {
        try { encodeEvent(event); }
        catch (IOException e) { throw new java.io.UncheckedIOException(e); }
    }

    private void encodeEvent(PortEvent event) throws IOException {
        switch (event) {
            case PortEvent.WorkspaceActivityChanged changed -> emit("workspaceActivityChanged", generation(changed.generation()));
            case PortEvent.PreparseStarted started -> emit("preparseStarted", generation(started.generation()));
            case PortEvent.PreparseProgress progress -> emit("preparseProgress", generation(progress.generation())
                    .put("done", progress.done()).put("total", progress.total()));
            case PortEvent.PreparseFinished finished -> {
                var result = finished.result();
                var value = json.createObjectNode().put("path", result.path()).put("status", result.status().name())
                        .put("errorKey", result.errorKey()).put("errorDetail", result.errorDetail())
                        .put("text", result.text()).put("textAssigned", result.textAssigned())
                        .put("title", result.title()).put("titleAssigned", result.titleAssigned());
                emit("preparseFinished", generation(finished.generation()).set("result", codec.file(value)));
            }
            case PortEvent.WorkspaceChanged changed -> {
                if (importing || applyingPlan) importChanges.add(changed.kind());
                else emit("workspaceChanged", json.createObjectNode().put("kind", changed.kind()));
            }
            case PortEvent.ImportStateChanged state -> {
                importing = state.importing();
                if (!importing) flushImportChanges();
                emit("importStateChanged", generation(state.generation()).put("importing", state.importing()));
            }
            case PortEvent.ImportRound round -> {
                flushImportChanges();
                var groups = json.createArrayNode();
                var snapshot = port.queries().workspace();
                for (var group : round.createdGroups()) groups.add(codec.group(snapshot.groups().stream()
                        .filter(vm -> vm.no() == group.getGroupNo()).findFirst().orElseThrow()));
                var data = generation(round.generation()).put("newFiles", round.newFiles()).put("newGroups", round.newGroups())
                        .put("madeListNonEmpty", round.madeListNonEmpty());
                data.set("plan", codec.file(json.valueToTree(round.plan())));
                data.set("createdGroups", codec.file(groups));
                emit("importRound", data);
            }
            case PortEvent.ImportFinished finished -> {
                importDone = true;
                emit("importFinished", generation(finished.generation())
                        .put("count", finished.accumulatedPaths().size()).put("failed", importFailed)
                        .set("accumulatedPaths", codec.file(json.valueToTree(finished.accumulatedPaths()))));
            }
            case PortEvent.Notice notice -> {
                importFailed = true;
                emit("notice", json.createObjectNode().put("key", notice.key()).put("level", notice.level().name())
                        .set("namedParams", json.valueToTree(notice.namedParams())));
            }
            case PortEvent.PreviewLoadStateChanged state -> {
                if (state.active()) {
                    var item = item(state.path());
                    previewInputs.put(state.generation(), previewService.prepare(Path.of(state.path()), params(item, activityImageMode)));
                }
                emit("previewLoadStateChanged", generation(state.generation()).put("path", state.path()).put("active", state.active()));
            }
            case PortEvent.PreviewConfirmationRequired required -> emit("previewConfirmationRequired", json.createObjectNode()
                    .put("path", required.path()).put("name", required.name()).put("sizeMiB", required.sizeMiB()));
            case PortEvent.PreviewLoadFailed failed -> {
                previewInputs.remove(failed.generation());
                emit("previewLoadFailed", generation(failed.generation()).put("path", failed.path())
                        .put("fileInfo", failed.fileInfo()).put("detail", failed.detail()));
            }
            case PortEvent.PreviewThumbnail thumbnail -> {
                var prepared = previewInputs.get(thumbnail.generation());
                if (prepared == null) throw new IOException("Missing preview input");
                var meta = previews.store().load(prepared.cacheKey()).orElseThrow(() -> new IOException("Missing preview cache"));
                var data = image(meta, thumbnail.index(), thumbnail.thumbnail());
                data.put("generation", thumbnail.generation()).put("path", thumbnail.path()).put("index", thumbnail.index());
                emit("previewThumbnail", data);
            }
            case PortEvent.PreviewLoaded loaded -> {
                var data = generation(loaded.generation()).put("path", loaded.path());
                var item = item(loaded.path());
                if (item.cachedMeta != null && loaded.generation() == port.queries().previewGeneration()) {
                    exportLoaded(loaded, item, data);
                } else {
                    data.putNull("manifest");
                    emit("previewLoaded", data);
                }
                previewInputs.remove(loaded.generation());
            }
            case PortEvent.PreviewRegionConfirmationRequired required -> emit("previewRegionConfirmationRequired",
                    generation(required.generation()).put("path", required.path()));
            case PortEvent.PreviewNotice notice -> {
                if (pendingNotices.containsKey(notice.generation())) {
                    pendingNotices.get(notice.generation()).add(notice);
                    return;
                }
                var args = json.createObjectNode();
                var meta = item(notice.path()).cachedMeta;
                if (meta != null) meta.warnings().stream().filter(w -> w.key().equals(notice.key()))
                        .findFirst().ifPresent(w -> w.args().forEach(args::put));
                emit("previewNotice", generation(notice.generation()).put("path", notice.path()).put("key", notice.key())
                        .set("namedParams", args));
            }
            case PortEvent.ParamStateChanged changed -> {
                // The GUI host already resets derived preview state after parameter events.
                // This host must also discard in-memory references to invalidated cache files.
                var affected = new java.util.HashSet<>(changed.affectedPaths());
                for (var item : model.allItems()) if (affected.contains(item.path)) item.resetPreviewState();
                emit("paramsChanged", json.createObjectNode()
                        .put("kind", changed.kind().name()).put("affectedCount", changed.affectedPaths().size())
                        .put("imageMode", changed.imageMode())
                        .set("affectedPaths", codec.file(json.valueToTree(changed.affectedPaths()))));
            }
            case PortEvent.ExtractionProgress progress -> {
                rawProgress++;
                int bucket = (int) (Math.clamp(progress.overall(), 0, 1) * 100);
                if (bucket > progressBucket) {
                    progressBucket = bucket;
                    sentProgress++;
                    emit("extractionProgress", json.createObjectNode().put("generation", progress.generation())
                            .put("overall", progress.overall()));
                }
            }
            case PortEvent.ExtractionTerminal end -> {
                terminal = end;
                emit("extractionTerminal", terminalSummary(end));
            }
            default -> { } // Extraction/result additions remain P5a-1d; never send thumbnail pixels.
        }
    }

    private ObjectNode generation(long value) { return json.createObjectNode().put("generation", value); }

    private void flushImportChanges() {
        var changes = List.copyOf(importChanges);
        importChanges.clear();
        for (var kind : changes) emit("workspaceChanged", json.createObjectNode().put("kind", kind));
    }

    private PreviewItem item(String path) {
        return model.allItems().stream().filter(it -> it.path.equals(path)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("Imported item required"));
    }

    private ObjectNode image(com.mhtextractor.cache.PreviewCacheMeta meta, int index, ThumbnailData thumbnail) throws IOException {
        Path path = previews.store().imageFileFor(meta, index);
        String ext = IpcImages.extension(Files.readAllBytes(path));
        var ref = files.borrowImage(path, IpcImages.mediaType(ext));
        return ref.put("imagePath", path.toString()).put("extension", ext).put("coreName", thumbnail.coreName())
                .put("width", thumbnail.width()).put("height", thumbnail.height());
    }

    private void exportLoaded(PortEvent.PreviewLoaded loaded, PreviewItem item, ObjectNode data) throws IOException {
        var manifest = json.createObjectNode();

package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.ExtractionStats;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.uiport.Confirmer;
import com.mhtextractor.uiport.ConfirmRequest;
import com.mhtextractor.uiport.PortEvent;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.LongSupplier;
import java.util.function.Supplier;

/**
 * 提取任务通道的唯一所有者（P3-B6，矩阵处置项 1）—— 把 {@code gui.ExtractionTaskCoordinator} 的
 * <b>任务代际、终态恰好一次、取消竞态、结果通道</b>整体下沉到 app 层（零 JavaFX），前端只剩事件渲染。
 *
 * <p><b>通道契约（逐字保留，这是本批核心）</b>：</p>
 * <ol>
 *   <li><b>每任务一代际</b>：{@link #generation()} 每 {@link #startExtraction} 递增一次；旧任务迟到的
 *       终态/回写/进度回调在派发目标线程上发现 {@code runId != generation} 而 <b>no-op</b>，
 *       不得污染新任务；</li>
 *   <li><b>终态恰好一次</b>：成功 / 取消 / 失败都恰好交付一次
 *       {@link PortEvent.ExtractionTerminal}（成功/失败在 worker 收尾后、取消在
 *       {@link #cancelExtraction} 的<b>取消请求时刻</b> —— 取消请求 ≠ worker 已退出，不得等 worker；
 *       取消与自然完成的裁决以 {@link RunChannel#result} 是否已完成等价
 *       {@code FutureTask.cancel} 对已完成任务 no-op 的语义）；</li>
 *   <li><b>不得把派发器当隐式同步契约</b>：配额/计数类读取必须先有显式完成信号 ——
 *       回写只经 {@link RunChannel#deliverAfterWorkerFinished}（{@code result} 完成之后、
 *       派发目标线程上、执行前复查陈旧守卫），事件本身即显式信号；</li>
 *   <li><b>取消后立即再开新任务不得互相污染</b>：新任务换新 {@link RunChannel}（新 runId），
 *       旧通道的一切迟到投递被代际守卫拦下。</li>
 * </ol>
 *
 * <p><b>线程约定</b>：{@link #startExtraction} / {@link #cancelExtraction} 在宿主串行线程（生产 = FX）
 * 调用；worker 只计算局部结果并经 {@link RunChannel#result}（{@link CompletableFuture}）与
 * {@code cancelled}/{@code failure}（volatile）向派发目标线程交付；一切事件投递经注入的派发器
 * （生产 = {@code Platform::runLater}）。</p>
 *
 * <p><b>本类零 JavaFX、零 I18n</b>（日志键 {@code log.maincontroller.31/32/33/37/39} 经 {@link Texts}
 * 逐键不变；回写与终态渲染是前端的事，本类只发事件）。</p>
 */
@Slf4j
public final class WorkspaceExtractionCoordinator {

    /**
     * 每次 {@link #startExtraction} 的结果通道与陈旧守卫（原 {@code ExtractionTaskCoordinator.RunChannel}
     * 逐字下沉，B —— 零 JavaFX，可无头单测）。
     *
     * <p><b>三个时点</b>：① 请求取消（{@link WorkspaceExtractionCoordinator#cancelExtraction} 立即置
     * {@link #cancelled} 并触发取消终态）② worker 停止并产出 partial（{@code call()} 返回前
     * {@link #result} 完成）③ 派发目标线程收到回写并投递。① ≠ ②：取消终态跑在①，此刻 partial
     * 尚不存在 —— 直接读 {@code lastExtractStats} 会拿到 null（首次运行）或上一次运行的残留。
     * 因此取消回写不读 holder，只在本通道上挂"②完成后投递一次"的回调。</p>
     *
     * <p><b>陈旧守卫</b>：新 run 一开（代际递增），旧 run 的一切迟到回调（终态与本通道挂的回写）
     * 都在派发目标线程上发现 {@code runId != generation} 而 no-op —— 取消后立即再开新任务时
     * 旧回调不得污染新任务。</p>
     */
    public static final class RunChannel {
        /** 本次 run 的序号（每 run 递增一次；旧任务回调凭它识别自己是陈旧调用） */
        public final long runId;
        /** 本次 run 的结果容器：worker 完成处理后在 worker 线程完成，<b>恰好一次</b>（异常路径完成 null） */
        public final CompletableFuture<ExtractionStats> result = new CompletableFuture<>();
        /** 到"宿主线程"的派发器（生产 = {@code Platform::runLater}；测试注入由测试线程按序 drain 的队列） */
        final Consumer<Runnable> dispatcher;
        /** 取消请求标志（worker 的取消信号轮询源；取消请求 ≠ worker 已退出） */
        volatile boolean cancelled;
        /** 在途 worker 线程（取消时打断；中断被吞时 worker 仍须完成处理并产出 partial 才算停） */
        volatile Thread worker;
        /** worker 异常（终态 FAILED 的判定源） */
        volatile Throwable failure;
        /** 本次 run 的会话输出目录（终态事件载荷，成功路径"完成后打开目录"用） */
        volatile String sessionOutputFolder;

        public RunChannel(long runId, Consumer<Runnable> dispatcher) {
            this.runId = runId;
            this.dispatcher = dispatcher;
        }

        /**
         * 终态回调的陈旧守卫：{@code currentRunId == runId} 才是当前 run。
         * 必须在派发目标线程上调用（代际只在派发目标线程上读写）。
         */
        public boolean isCurrent(long currentRunId) {
            return currentRunId == runId;
        }

        /**
         * 在 worker 完成处理后经派发器投递一次回写 —— <b>取消路径专用</b>（成功路径统计随终态事件走，避免双回写）。
         *
         * <p>注册时机是取消请求（时点①）；回写动作在 {@link #result} 完成（时点②）之后、
         * 派发目标线程（时点③）上执行，且执行前<b>复查陈旧守卫</b> —— 注册之后又开了新 run，
         * 本次回写必须 no-op。回调无论注册时 {@code result} 是否已完成都恰好执行一次
         * （{@link CompletableFuture#whenComplete} 对已完成 future 仍会执行）；
         * worker 异常路径完成 null 时回写动作不触发（无统计可回写）。</p>
         *
         * @param currentRunId 当前 run 序号的只读入口（在派发目标线程上求值）
         * @param onFx         UI 回写动作（只收非 null 统计）
         */
        public void deliverAfterWorkerFinished(LongSupplier currentRunId,
                                               Consumer<ExtractionStats> onFx) {
            result.whenComplete((stats, error) -> dispatcher.accept(() -> {
                if (currentRunId.getAsLong() != runId) {
                    return;                     // 陈旧 run 的迟到回写：no-op
                }
                if (stats != null) {
                    onFx.accept(stats);
                }
            }));
        }

        /** 取消请求（时点①）：置取消标志 + 打断 worker（中断可能被吞，取消请求 ≠ worker 已退出）。 */
        void cancel() {
            cancelled = true;
            Thread w = worker;
            if (w != null) {
                w.interrupt();
            }
        }
    }

    /**
     * 运行标记（预解析/预览回调据此让出进度条 / 状态栏）：{@code startExtraction} 里置 true，
     * 终态（成功/失败 = worker 收尾投递；取消 = {@link #cancelExtraction} 请求时刻）复位 false。
     */
    public final AtomicBoolean running = new AtomicBoolean(false);
    /**
     * 最近一次提取统计的唯一 holder：worker 在服务返回后写一次（先落 holder，再完成结果通道），
     * 经 GUI 只读投影供自动化断言。取消回写不经此 holder（见 {@link RunChannel}）。
     */
    public final AtomicReference<ExtractionStats> lastExtractStats = new AtomicReference<>();
    /** 每 run 递增的运行代数（只在派发目标线程上读写）：旧任务迟到的终态回调凭它识别自己是陈旧调用 */
    private volatile long generation;
    /** 在途通道（null = 无在途任务；取消与终态投递只在派发目标线程访问） */
    private volatile RunChannel channel;

    private final WorkspaceExtractionService service;
    private final Function<Boolean, WorkspaceExtractionService.ExtractionRequest> requests;
    private final Consumer<Runnable> dispatcher;
    private final List<Consumer<PortEvent>> listeners = new CopyOnWriteArrayList<>();

    /**
     * @param service    提取业务段（逐单元调用 processor、进度聚合、统计累计、取消传播）
     * @param requests   请求工厂（{@code checkedOnly} → 不可变请求快照；生产 =
     *                   {@link #productionRequests(ExtractionPlanService, Supplier, Confirmer)}，
     *                   在宿主串行线程上求值 —— 与迁移前 {@code startExtractionTask} 的快照时机一致；
     *                   测试注入桩工厂复现闸门/自定义单元）
     * @param dispatcher 到宿主串行线程的派发器（生产 = {@code Platform::runLater}）
     */
    public WorkspaceExtractionCoordinator(WorkspaceExtractionService service,
                                          Function<Boolean, WorkspaceExtractionService.ExtractionRequest> requests,
                                          Consumer<Runnable> dispatcher) {
        this.service = java.util.Objects.requireNonNull(service, "service");
        this.requests = java.util.Objects.requireNonNull(requests, "requests");
        this.dispatcher = java.util.Objects.requireNonNull(dispatcher, "dispatcher");
    }

    /** 端口事件订阅（事件在派发目标线程同步送达；句柄 {@code close()} 即退订）。 */
    public AutoCloseable subscribe(Consumer<PortEvent> listener) {
        listeners.add(listener);
        return () -> listeners.remove(listener);
    }

    private void emit(PortEvent event) {
        for (Consumer<PortEvent> listener : listeners) {
            listener.accept(event);
        }
    }

    /** 运行代数（每 {@link #startExtraction} 递增一次）。 */
    public long generation() {
        return generation;
    }

    /** 在途通道（无在途任务时为 null）。 */
    public RunChannel channel() {
        return channel;
    }

    /**
     * 创建并启动提取任务（<b>必须在宿主串行线程调用</b>）：请求在调用线程上求值（快照时机与
     * 迁移前 {@code startExtractionTask} 一致），随后置运行标记、建新通道（代际递增）、启动 worker。
     * 界面锁定（开始/停止按钮、进度条归零）由前端在调用本命令前完成（渲染属前端）。
     */
    public void startExtraction(boolean checkedOnly) {
        WorkspaceExtractionService.ExtractionRequest request = requests.apply(checkedOnly);
        RunChannel ch = new RunChannel(++generation, dispatcher);
        ch.sessionOutputFolder = request.sessionOutputFolder();
        channel = ch;
        running.set(true);
        Thread worker = new Thread(() -> {
            try {
                ExtractionStats stats = WorkspaceExtractionService.statsFrom(service.run(request,
                        () -> ch.cancelled,
                        overall -> dispatcher.accept(() -> {
                            if (ch.isCurrent(generation)) {
                                emit(new PortEvent.ExtractionProgress(generation, overall));
                            }
                        })).stats());
                // 时点②：worker 停止并产出 partial —— 先落只读 holder，再完成本 run 的结果通道
                lastExtractStats.set(stats);
                ch.result.complete(stats);
            } catch (Throwable e) {
                // Throwable 而非 Exception：迁移前 JavaFX Task 框架把 Error 一视同仁路由到 onFailed
                // （终态 FAILED 恰好一次）；只捕 Exception 会让 Error 把通道晾死（result 永不完成、
                // 无终态、运行标记卡在 true），语义放窄 —— 终态恰好一次契约对 Error 同样成立。
                ch.failure = e;
                log.error(Texts.msg("log.maincontroller.37"), e);
                ch.result.complete(null);   // worker 异常：通道仍收尾（无统计可回写），终态按 FAILED 交付
            }
            dispatcher.accept(() -> landAfterWorkerFinished(ch));
        });
        ch.worker = worker;
        worker.start();
    }

    /**
     * 取消在途提取任务（<b>必须在宿主串行线程调用</b>；无在途任务或 worker 已收尾时为空操作 ——
     * 后者等价 {@code FutureTask.cancel} 对已完成任务 no-op，终态已在途）。
     *
     * <p><b>时点①</b>：取消请求 ≠ worker 已退出 —— 运行标记<b>立即</b>复位、取消终态
     * {@link PortEvent.ExtractionTerminal}（{@code CANCELLED}，stats = null）<b>此刻</b>交付一次
     * （前端据此复位停止/开始按钮）；partial 回写经 {@link RunChannel#deliverAfterWorkerFinished}
     * 在 worker 完成（时点②）后投递一次（时点③），载荷 = worker 返回的统计。</p>
     */
    public void cancelExtraction() {
        RunChannel ch = channel;
        if (ch == null || ch.result.isDone()) {
            return;                     // 无在途任务 / worker 已收尾：终态已在途，不得再交付第二次
        }
        ch.cancel();
        running.set(false);
        emit(new PortEvent.ExtractionTerminal(ch.runId, PortEvent.ExtractionEnd.CANCELLED, null,
                ch.sessionOutputFolder));
        // 取消回写：worker 完成后经派发器投递一次（陈旧守卫在派发目标线程复查）
        ch.deliverAfterWorkerFinished(this::generation,
                stats -> emit(new PortEvent.ExtractionResult(generation, stats)));
    }

    /** worker 收尾后的终态投递（派发目标线程）：陈旧守卫 → 取消 run 不重复交付终态（回写通道负责 partial）→ 成功/失败终态恰好一次。 */
    private void landAfterWorkerFinished(RunChannel ch) {
        if (!ch.isCurrent(generation)) {
            return;                     // 陈旧任务的迟到回调：no-op（取消后立即再开新任务时不得污染新任务）
        }
        if (ch.cancelled) {
            return;                     // 取消终态已在 cancelExtraction（时点①）交付；partial 回写走结果通道
        }
        running.set(false);
        if (ch.failure != null) {
            emit(new PortEvent.ExtractionTerminal(ch.runId, PortEvent.ExtractionEnd.FAILED, null,
                    ch.sessionOutputFolder));
        } else {
            emit(new PortEvent.ExtractionTerminal(ch.runId, PortEvent.ExtractionEnd.SUCCEEDED,
                    ch.result.getNow(null), ch.sessionOutputFolder));
        }
    }

    // ==================== 生产请求工厂 ====================

    /**
     * 生产请求工厂（原 {@code ExtractionTaskCoordinator.startExtractionTask} 的请求组装段逐字下沉）：
     * 运行时配置 → 时间戳会话目录（{@code log.maincontroller.31/32}）→ 功能一勾选计数
     * （{@code log.maincontroller.39}）→ 输出单元计划（{@code log.maincontroller.33}）→
     * 逐文件覆盖 → 不可变请求快照。递归深度超限确认经端口确认往返（等待方是提取后台线程，
     * 不阻塞宿主；文案与迁移前 {@code recursionDecision} 逐字一致）。
     *
     * @param plans           提取计划服务（运行时配置 + 输出单元规划 + 逐文件覆盖；上下文由宿主注入）
     * @param allVisibleItems 全部有效项目（removed == false，含组内成员；在调用线程上求值）
     * @param confirmer       确认往返实现（递归深度卡；前端渲染卡片，后端线程阻塞等待）
     */
    public static Function<Boolean, WorkspaceExtractionService.ExtractionRequest> productionRequests(
            ExtractionPlanService plans, Supplier<List<PreviewItem>> allVisibleItems, Confirmer confirmer) {
        java.util.Objects.requireNonNull(plans, "plans");
        java.util.Objects.requireNonNull(allVisibleItems, "allVisibleItems");
        java.util.Objects.requireNonNull(confirmer, "confirmer");
        return checkedOnly -> {
            AppConfig runtime = plans.runtimeConfig();
            // 生成时间戳会话目录，隔离每次提取运行
            String timestamp = LocalDateTime.now()
                    .format(DateTimeFormatter.ofPattern(Texts.get("params.datetimeFormat")));
            String sessionOutputFolder = new File(runtime.getOutputFolder(), timestamp).getPath();
            if (!new File(sessionOutputFolder).mkdirs()) {
                log.warn(Texts.msg("log.maincontroller.31", sessionOutputFolder));
            }
            log.info(Texts.msg("log.maincontroller.32", sessionOutputFolder));

            // 功能一：只提取选中项时的勾选计数（清空"本次不参与的可见项"的旧结果色由前端在命令前完成）
            if (checkedOnly) {
                List<PreviewItem> visible = allVisibleItems.get();
                log.info(Texts.msg("log.maincontroller.39",
                        visible.stream().filter(i -> i.selected).count(), visible.size()));
            }

            // 构建输出单元计划（宿主线程快照；计划与单元参数补充在 app.ExtractionPlanService）
            plans.setSessionOutputFolder(sessionOutputFolder);
            List<com.mhtextractor.uiport.OutputUnitVm> units = plans.outputUnitPlan(checkedOnly);
            log.info(Texts.msg("log.maincontroller.33", units.stream()
                    .map(u -> Texts.get("extract.groupFileCount",
                            "group", u.outputName() != null ? u.outputName() : Texts.get(u.labelKey()),
                            "count", u.fileCount())).toList()));
            Map<String, com.mhtextractor.processor.PerFileOverrides> overrides =
                    ExtractionPlanService.overrides(allVisibleItems.get());

            return WorkspaceExtractionService.fromPlan(sessionOutputFolder, units, overrides,
                    runtime.isImageModeEnabled(), recursionDecision(confirmer));
        };
    }

    /**
     * 递归深度超限回调：经端口确认往返（后端工作线程阻塞等待答案，卡片由前端渲染）。
     * 确定 = 继续；取消/中断 = 跳过（与迁移前 {@code Platform.runLater + future.join} 同语义）。
     */
    private static Supplier<Boolean> recursionDecision(Confirmer confirmer) {
        return () -> {
            String msg = Texts.get("alert.recursionDepthHeader") + "\n"
                    + Texts.get("alert.recursionDepthContent")
                    + Texts.get("alert.recursionDepthContinue")
                    + Texts.get("alert.recursionDepthSkip");
            ConfirmRequest request = new ConfirmRequest("alert.recursionDepthHeader", Map.of(),
                    List.of(ACTION_CONTINUE), 0, msg);
            try {
                return ACTION_CONTINUE.equals(confirmer.confirm(request).await());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;               // 中断 = 跳过
            }
        };
    }

    /** 递归深度确认卡的「继续」动作键。 */
    static final String ACTION_CONTINUE = "continue";
}
package com.mhtextractor.model;

import java.util.List;

/**
 * 提取统计的中性 DTO（P3-3b-22 起为 gui 对 {@code processor.BatchProcessor.ProcessStats} 的只读快照；
 * P3-B6 随提取任务通道契约迁入 {@code model} —— 端口事件
 * {@code uiport.PortEvent.ExtractionTerminal} / {@code ExtractionResult} 的载荷类型，app 与 gui 共用）：
 * 摘要行 / 失败 / 跳过 / 警告 + 各文件结果。
 *
 * <p>数值口径、null/空处理、字段顺序逐字不变；{@code files} 与每条 {@code warnings} 均做不可变拷贝，
 * 顺序与原 {@code getFileResults()} 一致。</p>
 *
 * <p>本类<b>零 JavaFX、零 I18n</b>，属 {@code model} 层。从批量处理器统计的 1:1 搬运工厂
 * （原 {@code app.ExtractionStats.from}）留在 {@code app.WorkspaceExtractionService#statsFrom}
 * （工厂依赖 {@code processor}，model 不得反向依赖业务包）。</p>
 */
public record ExtractionStats(String summaryLine, int failCount, int skipCount, int warnCount,
                              List<FileOutcome> files) {

    /**
     * 单文件结果快照（{@code processor.FileResult} 的中性映射）：
     * 绝对路径 + 结果类型 + 详情 + 警告列表。
     */
    public record FileOutcome(String path, ExtractOutcome outcome, String message,
                              List<ExtractWarning> warnings) {
    }
}
     * 提取任务通道事件族（B6）：任务代际 / 终态恰好一次 / 取消竞态 / 结果通道的端口契约 ——
     * {@link ExtractionProgress} / {@link ExtractionTerminal} / {@link ExtractionResult}
     * 都携带递增的 run 代际；旧任务迟到的投递由后端代际守卫拦下（不得污染新任务）。
     */
    non-sealed interface ExtractionChannelEvent extends PortEvent {
    }

    /**
     * 跨单元总进度（0.0~1.0，只增不减；后端 worker 的进度回调经派发器投递）。
     *
     * @param generation run 代际
     * @param overall    总进度
     */
    record ExtractionProgress(long generation, double overall) implements ExtractionChannelEvent {
    }

    /**
     * 提取终态（B6）：<b>恰好一次</b> —— 成功 / 失败在 worker 收尾后交付；取消在
     * {@code cancelExtraction()} 的<b>取消请求时刻</b>交付（取消请求 ≠ worker 已退出）。
     * 前端据此复位停止/开始按钮并渲染结果。
     *
     * @param generation          run 代际
     * @param end                 终态类别
     * @param stats               统计快照（仅 {@link ExtractionEnd#SUCCEEDED} 非 null；
     *                             取消路径的 partial 经 {@link ExtractionResult} 单独交付）
     * @param sessionOutputFolder 本次会话输出目录（成功路径"完成后打开输出目录"用）
     */
    record ExtractionTerminal(long generation, ExtractionEnd end,
                              com.mhtextractor.model.ExtractionStats stats,
                              String sessionOutputFolder) implements ExtractionChannelEvent {
    }

    /**
     * 取消路径的 partial 回写（B6）：worker 完成处理（取消请求之后）恰好投递一次，
     * 载荷 = worker 返回的统计；成功路径统计随 {@link ExtractionTerminal} 走，不重复投递。
     *
     * @param generation run 代际
     * @param stats      已处理单元的 partial 统计
     */
    record ExtractionResult(long generation,
                            com.mhtextractor.model.ExtractionStats stats) implements ExtractionChannelEvent {
    }

    /** 提取终态类别（B6）：成功 / 失败 / 取消，每任务恰好交付其一。 */
    enum ExtractionEnd {
        /** worker 正常收尾（统计随终态事件交付） */
        SUCCEEDED,
        /** worker 异常收尾（无统计；后端已打 {@code log.maincontroller.37}，前端渲染错误卡片） */
        FAILED,
        /** 取消请求时刻交付（无统计；partial 经 {@link ExtractionResult} 在 worker 收尾后投递） */
        CANCELLED
    }

    /**
     * 工作区结构化变更（数据序 / 分组 / 勾选 / 参数 / 撤销等）。
     *
     * @param kind 变更类别（类别枚举留后续批次定稿；前端据此决定刷新粒度）
     */
    record WorkspaceChanged(String kind) implements PortEvent {
        public WorkspaceChanged {
            Objects.requireNonNull(kind, "kind");
        }
    }

    /**
     * 提取在途状态变更。
     *
     * @param running 提取是否在途
     */
    record RunningChanged(boolean running) implements PortEvent {}

    /**
     * 提醒（前端按 {@link NoticeLevel} 选择呈现形式：错误居中必点 / 警告·信息右上 toast）。
     *
     * @param key         文案键
     * @param namedParams 具名参数（防御性不可变拷贝）
     * @param level       级别
     */
    record Notice(String key, Map<String, String> namedParams, NoticeLevel level) implements PortEvent {
        public Notice {
            Objects.requireNonNull(key, "key");
            namedParams = Map.copyOf(Objects.requireNonNull(namedParams, "namedParams"));
            Objects.requireNonNull(level, "level");
        }
    }
}
