        // 取消回写迟到注册（取消请求到达时 worker 刚好已停）
        channel.deliverAfterWorkerFinished(generation::get, applied::add);

        assertEquals(1, drain(q), "对已完成 future 注册的回调仍应恰好投递一次");
        assertEquals(List.of(partial), applied);
