                    + Texts.get("alert.recursionDepthContent")
                    + Texts.get("alert.recursionDepthContinue")
                    + Texts.get("alert.recursionDepthSkip");
            ConfirmRequest request = new ConfirmRequest("alert.recursionDepthHeader", Map.of(),
